                Text = "\u1797\u17D2\u1793\u17C6\u1796\u17C1\u1789\u0020\u1782\u17BA\u1787\u17B6\u179A\u17B6\u1787\u1792\u17B6\u1793\u17B8\u179A\u1794\u179F\u17CB\u1796\u17D2\u179A\u17C7\u179A\u17B6\u1787\u17B6\u178E\u17B6\u1785\u1780\u17D2\u179A\u1780\u1798\u17D2\u1796\u17BB\u1787\u17B6\u0020\u178A\u17C2\u179B\u1798\u17B6\u1793\u1794\u17D2\u179A\u1787\u17B6\u1787\u1793\u179A\u179F\u17CB\u1793\u17C5\u1785\u17D2\u179A\u17BE\u1793\u1787\u17B6\u1784\u1798\u17BD\u1799\u179B\u17B6\u1793\u1793\u17B6\u1780\u17CB\u0020\u1793\u17B7\u1784\u0020\u1787\u17B6\u1791\u17B8\u1780\u17D2\u179A\u17BB\u1784\u1792\u17C6\u179B\u17C6\u178A\u17B6\u1794\u17CB\u1791\u17B8\u17E1\u0020\u178A\u17C2\u179B\u1798\u17B6\u1793\u1794\u17D2\u179A\u1787\u17B6\u1787\u1793\u179A\u179F\u17CB\u1793\u17C5\u1785\u17D2\u179A\u17BE\u1793\u1787\u17B6\u1784\u1782\u17C1\u1780\u17D2\u1793\u17BB\u1784\u1794\u17D2\u179A\u1791\u17C1\u179F\u1780\u1798\u17D2\u1796\u17BB\u1787\u17B6\u0020\u17D4\u0020\u1780\u17D2\u179A\u17BB\u1784\u1797\u17D2\u1793\u17C6\u1796\u17C1\u1789\u0020\u1787\u17B6\u1798\u1787\u17D2\u1788\u1798\u178E\u17D2\u178C\u179B\u1796\u17B6\u178E\u17B7\u1787\u17D2\u1787\u1780\u1798\u17D2\u1798\u178A\u17C2\u179B\u1794\u17D2\u179A\u1798\u17BC\u179B\u1795\u17D2\u178A\u17BB\u17C6\u1791\u17C5\u178A\u17C4\u1799\u0020\u179F\u17C6\u178E\u1784\u17CB\u17A2\u17B6\u1782\u17B6\u179A\u179B\u17C6\u1793\u17C5\u178A\u17D2\u178B\u17B6\u1793\u0020\u179F\u17B6\u179B\u17B6\u179A\u17C0\u1793\u0020\u1798\u1793\u17D2\u1791\u17B8\u1796\u17C1\u1791\u17D2\u1799\u0020\u179C\u178F\u17D2\u178F\u17A2\u17B6\u179A\u17B6\u1798\u0020\u1791\u17B8\u1795\u17D2\u179F\u17B6\u179A\u178A\u17C4\u17C7\u178A\u17BC\u179A\u1798\u17BB\u1781\u1791\u17C6\u1793\u17B7\u1789\u0020\u179B\u17BE\u1798\u17BB\u1781\u1787\u17C6\u1793\u17BD\u1789\u1787\u17BD\u1789\u178A\u17BC\u179A\u0020\u1791\u17B6\u17C6\u1784\u1780\u17D2\u1793\u17BB\u1784\u179F\u17D2\u179A\u17BB\u1780\u0020\u1793\u17B7\u1784\u0020\u1780\u17D2\u179A\u17C5\u179F\u17D2\u179A\u17BB\u1780\u0020\u1780\u17D2\u1793\u17BB\u1784\u179B\u17C6\u17A0\u17BC\u179A\u179F\u17B6\u1785\u17CB\u1794\u17D2\u179A\u17B6\u1780\u17CB\u1787\u17B6\u17A2\u178F\u17B7\u1794\u179A\u1798\u17B6\u0020\u178A\u17C2\u179B\u179A\u17BD\u1798\u1794\u1789\u17D2\u1785\u17BC\u179B\u1791\u17B6\u17C6\u1784\u179F\u17C1\u178A\u17D2\u178B\u1780\u17B7\u1785\u17D2\u1785\u1791\u17B8\u1795\u17D2\u179F\u17B6\u179A\u0020\u179F\u1784\u17D2\u1782\u1798\u1780\u17B7\u1785\u17D2\u1785\u0020\u1793\u17B7\u1784\u0020\u1793\u1799\u17C4\u1794\u17B6\u1799\u0020\u178A\u17C2\u179B\u1793\u17B6\u17C6\u17B1\u17D2\u1799\u1791\u17B8\u1780\u17D2\u179A\u17BB\u1784\u1791\u17B6\u17C6\u1784\u1798\u17BC\u179B\u1780\u17D2\u179B\u17B6\u1799\u1787\u17B6\u1791\u17B8\u1780\u1793\u17D2\u179B\u17C2\u1784\u179A\u179F\u17CB\u1793\u17C5\u1794\u17D2\u179A\u1780\u1794\u178A\u17C4\u1799\u1797\u17B6\u1796\u179F\u1798\u17D2\u1794\u17BC\u179A\u1794\u17C2\u1794\u0020\u17D4\u000A\u000A\u000A\u003D\u003D\u0020\u1794\u17D2\u179A\u179C\u178F\u17D2\u178F\u17B7\u1793\u17C3\u1791\u17B8\u1780\u17D2\u179A\u17BB\u1784\u0020\u003D\u003D\u000A\u1791\u17B8\u1780\u17D2\u179A\u17BB\u1784\u1797\u17D2\u1793\u17C6\u1796\u17C1\u1789\u178F\u17D2\u179A\u17BC\u179C\u1794\u17B6\u1793\u1794\u1784\u17D2\u1780\u17BE\u178F\u17A1\u17BE\u1784\u178A\u17C6\u1794\u17BC\u1784\u1780\u17D2\u1793\u17BB\u1784\u179A\u17B6\u1787\u0020\u1796\u17D2\u179A\u17C7\u1794\u179A\u1798\u179A\u17B6\u1787\u17B6\u1791\u17B8\u17E1\u0020\u1793\u17C3\u17A2\u1784\u17D2\u1782\u0020\u1796\u1789\u17D2\u1789\u17B6\u1799\u17C9\u17B6\u178F\u0020\u178A\u17C2\u179B\u1794\u17B6\u1793\u1794\u17D2\u179A\u1780\u17B6\u179F\u1787\u17B6\u1795\u17D2\u179B\u17BC\u179C\u1780\u17B6\u179A\u0020\u1780\u17D2\u1793\u17BB\u1784\u1786\u17D2\u1793\u17B6\u17C6\u0020\u17E1\u17E4\u17E0\u17E0\u0020\u1793\u17C3\u1782\u002E\u179F\u0020\u178F\u17D2\u179A\u17BC\u179C\u1793\u17B9\u1784\u0020\u179F\u002E\u179C\u1791\u17B8\u17E1\u17E5\u0020\u17D4\u0020\u1780\u17D2\u179A\u17BB\u1784\u1797\u17D2\u1793\u17C6\u1796\u17C1\u1789\u0020\u1794\u17B6\u1793\u1785\u17B6\u1794\u17CB\u1795\u17D2\u178A\u17BE\u1798\u179F\u17B6\u1784\u179F\u1784\u17CB\u17A1\u17BE\u1784\u1780\u17D2\u1793\u17BB\u1784\u1786\u17D2\u1793\u17B6\u17C6\u0020\u17E1\u17E3\u17E9\u17E7\u0020\u1793\u17C3\u1782\u002E\u179F\u0020\u17A2\u17C6\u17A1\u17BB\u1784\u1796\u17C1\u179B\u178A\u17C2\u179B\u179A\u17B6\u1787\u1792\u17B6\u1793\u17B8\u1791\u17BD\u179B\u1794\u17B6\u179F\u17B6\u1793\u0020\u1793\u17B6\u1781\u17C1\u178F\u17D2\u178F\u0020\u1780\u17C6\u1796\u1784\u17CB\u1785\u17B6\u1798\u0020\u178F\u17D2\u179A\u17BC\u179C\u1794\u17B6\u1793\u1791\u17B9\u1780\u1787\u17C6\u1793\u1793\u17CB\u1787\u1793\u17CB\u179B\u17B7\u1785\u0020\u17A0\u17BE\u1799\u1796\u17D2\u179A\u17C7\u179A\u17B6\u1787\u17B6\u1794\u17B6\u1793\u1795\u17D2\u179B\u17B6\u179F\u17CB\u179A\u17B6\u1787\u1792\u17B6\u1793\u17B8\u1798\u1780\u178F\u17C6\u1794\u1793\u17CB\u1785\u178F\u17BB\u1798\u17BB\u1781\u0020\u178A\u17BE\u1798\u17D2\u1794\u17B8\u1780\u179F\u17B6\u1784\u1791\u17B8\u1780\u17D2\u179A\u17BB\u1784\u1793\u17C1\u17C7\u17A1\u17BE\u1784\u0020\u178A\u17C2\u179B\u1794\u17D2\u179A\u17BE\u1796\u17C1\u179B\u179F\u17B6\u1784\u179F\u1784\u17CB\u17A2\u179F\u17CB\u179A\u1799\u17C8\u1796\u17C1\u179B\u0020\u17E3\u1786\u17D2\u1793\u17B6\u17C6\u0020\u1791\u17BE\u1794\u1789\u17D2\u1785\u1794\u17CB\u1780\u17D2\u1793\u17BB\u1784\u1786\u17D2\u1793\u17B6\u17C6\u0020\u17E1\u17E4\u17E0\u17E0\u0020\u1793\u17C3\u1782\u002E\u179F\u0020\u17A0\u17BE\u1799\u1791\u17D2\u179A\u1784\u17CB\u1794\u17B6\u1793\u1794\u17D2\u179A\u1780\u17B6\u179F\u179A\u17B6\u1787\u1792\u17B6\u1793\u17B8\u1790\u17D2\u1798\u17B8\u1793\u17C1\u17C7\u1790\u17B6\u0020\u000A\u0022\u1780\u17D2\u179A\u17BB\u1784\u1785\u178F\u17BB\u1798\u17BB\u1781\u0020\u1798\u1784\u17D2\u1782\u179B\u179F\u1780\u179B\u1780\u1798\u17D2\u1796\u17BB\u1787\u17B6\u1792\u17B7\u1794\u178F\u17B8\u0020\u179F\u17B7\u179A\u17B8\u1792\u179A\u17C8\u1794\u179C\u179A\u0020\u17A5\u1793\u17D2\u1791\u1794\u178F\u17D2\u178F\u1794\u17BB\u179A\u17B8\u0020\u179A\u178A\u17D2\u178B\u179A\u17B6\u1787\u179F\u17B8\u1798\u17B6\u1798\u17A0\u17B6\u1793\u1782\u179A\u0022\u0020\u178A\u17C2\u179B\u178F\u17D2\u179A\u17BC\u179C\u1794\u17B6\u1793\u17A0\u17C5\u1780\u17B6\u178F\u17CB\u1790\u17B6\u0020\u0022\u1780\u17D2\u179A\u17BB\u1784\u1785\u178F\u17BB\u1798\u17BB\u1781\u0022\u0020\u17D4\u000A\u000A\u000A\u003D\u003D\u0020\u1780\u17B6\u179A\u1794\u17C4\u17C7\u1794\u1784\u17CB\u1791\u17B8\u1780\u17D2\u179A\u17BB\u1784\u179B\u17BE\u1780\u1791\u17B8\u17E1\u0020\u003D\u003D\u000A\u1791\u17B8\u1780\u17D2\u179A\u17BB\u1784\u1797\u17D2\u1793\u17C6\u1796\u17C1\u1789\u0020\u178F\u17D2\u179A\u17BC\u179C\u1794\u17B6\u1793\u1794\u17C4\u17C7\u1794\u1784\u17CB\u1785\u17C4\u179B\u1787\u17B6\u179B\u17BE\u1780\u178A\u17C6\u1794\u17BC\u1784\u0020\u17A2\u17C6\u17A1\u17BB\u1784\u1796\u17C1\u179B\u178A\u17C2\u179B\u1780\u1798\u17D2\u1796\u17BB\u1787\u17B6\u1798\u17B6\u1793\u1787\u1798\u17D2\u179B\u17C4\u17C7\u179A\u17B6\u1787\u179C\u1784\u17D2\u179F\u178A\u178E\u17D2\u178A\u17BE\u1798\u179A\u17B6\u1787\u0020\u1793\u17C5\u1782\u002E\u179F\u1780\u179A\u17B6\u1787\u0020\u17E1\u17E4\u17E6\u17E1\u0020\u1796\u17D2\u179A\u17C7\u179F\u17D2\u179A\u17B8\u179F\u17BB\u179A\u17B7\u1799\u17C4\u1791\u17D0\u1799\u0020\u178A\u17C2\u179B\u178F\u17D2\u179A\u17BC\u179C\u1787\u17B6\u1796\u17D2\u179A\u17C7\u1793\u17BB\u1787\u0020\u0028\u1794\u17D2\u17A2\u17BC\u1793\u1794\u1784\u17D2\u1780\u17BE\u178F\u0029\u0020\u1796\u17D2\u179A\u17C7\u179F\u17D2\u179A\u17B8\u179A\u17B6\u1787\u17B6\u0020\u1794\u17B6\u1793\u1792\u17D2\u179C\u17BE\u179A\u179A\u17B6\u1787\u1794\u17D2\u179A\u17A0\u17B6\u179A\u178A\u178E\u17D2\u178A\u17BE\u1798\u1799\u1780\u179A\u17B6\u1787\u1794\u179B\u17D2\u179B\u17D0\u1784\u178A\u17C4\u1799\u1798\u17B6\u1793\u1780\u17B6\u179A\u1787\u1798\u17D2\u179A\u17BB\u1789\u1796\u17B8\u1796\u17BD\u1780\u1798\u1793\u17D2\u178F\u17D2\u179A\u17B8\u1780\u17D2\u1794\u178F\u17CB\u1780\u17D2\u1793\u17BB\u1784\u1787\u17BD\u179A\u1798\u1793\u17D2\u178F\u17D2\u179A\u17B8\u1793\u17C3\u1798\u17BB\u1781\u1784\u